function read(storage,s){const rows=J.read(storage,s.key,[]),ids=new Set();for(const x of rows){if(!x||typeof x.id!=='string'||x.company!==s.company||x.endpoint!==s.endpoint||x.payload?.p_empresa!==s.company||!['pendente','enviando','enviado','erro','conflito'].includes(x.status)||!Array.isArray(x.history)||typeof x.signature!=='string'||!Number.isSafeInteger(x.attempts)||x.attempts<0||ids.has(x.id))throw Error('Fila inválida; conteúdo preservado para recuperação');ids.add(x.id);}return rows;}
async function enqueue(storage,s,payload,now=new Date().toISOString()){if(payload.p_empresa!==s.company)throw Error('A empresa do envio não corresponde ao contexto');const signature=await fingerprint(payload),before=storage.getItem(s.key),rows=read(storage,s);const existing=rows.find(x=>x.signature===signature);if(existing)return structuredClone(existing);const job={id:crypto.randomUUID(),endpoint:s.endpoint,company:s.company,payload:structuredClone(payload),signature,status:'pendente',attempts:0,createdAt:now,history:[{at:now,status:'pendente'}]};rows.push(job);J.write(storage,s.key,rows,before);return job;}
function transition(storage,s,id,patch,event){const before=storage.getItem(s.key),rows=read(storage,s),job=rows.find(x=>x.id===id);if(!job)throw Error('Envio não encontrado');Object.assign(job,patch);job.history.push(event);J.write(storage,s.key,rows,before);return structuredClone(job);}
