 try{if(await fingerprint(job.payload)!==job.signature)throw Error('Conflito: conteúdo da fila alterado');const current=await currentPayload(job);if(await fingerprint(current)!==job.signature)throw Error('Conflito: RDO, vínculos ou revisão mudaram; prepare novo envio após conferir');}catch(e){transition(storage,s,job.id,{status:'conflito',lastError:e.message},{at:now(),status:'conflito',message:e.message});summary.conflicts++;onProgress(summary);continue;}
 job=transition(storage,s,job.id,{status:'enviando',attempts:job.attempts+1,lastAttemptAt:now(),lastError:''},{at:now(),status:'enviando'});
